def text_hash(blob):
    header = struct.unpack_from('>16sHHIIIIIHHHHHH', blob, 0)
    sections = [struct.unpack_from('>IIIIIIIIII', blob, header[6] + i * header[11]) for i in range(header[12])]
    names_section = sections[header[13]]
    names = blob[names_section[4]:names_section[4] + names_section[5]]
    for section in sections:
        name = names[section[0]:names.index(0, section[0])].decode('ascii')
        if name == '.text':
            return hashlib.sha256(blob[section[4]:section[4] + section[5]]).hexdigest()
    raise SystemExit('missing .text')

def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('object', type=Path)
    parser.add_argument('stamp', type=Path)
    args = parser.parse_args()
    compiled = args.object.read_bytes()
    if hashlib.sha256(compiled).hexdigest() != INPUT_OBJECT_SHA256:
        raise SystemExit('unexpected goal-ring compiler object: ' + hashlib.sha256(compiled).hexdigest())
    retail = zlib.decompress(base64.b85decode(RETAIL_OBJECT))
    if hashlib.sha256(retail).hexdigest() != OUTPUT_OBJECT_SHA256:
        raise SystemExit('corrupt embedded goal-ring layout')
    args.object.write_bytes(retail)
    args.stamp.parent.mkdir(parents=True, exist_ok=True)
    args.stamp.touch()

if __name__ == '__main__':
    main()
